                (y, x)
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
                if grid[y][x] == 0
            }
            reachable = {
                (y, x) for y, x in background
                if y == top or y == bottom or x == left or x == right
            }
            flood = list(reachable)
            while flood:
                y, x = flood.pop()
                for ny, nx in ((y - 1, x), (y + 1, x),
                               (y, x - 1), (y, x + 1)):
                    if (ny, nx) in background and (ny, nx) not in reachable:
                        reachable.add((ny, nx))
                        flood.append((ny, nx))

            objects.append({
                "color": color,
                "cells": cells,
                "top": top,
                "bottom": bottom,
                "closed": len(reachable) < len(background),
            })

    result = [[0] * w for _ in range(h)]

    def move_group(group, direction):
        # Objects nearest the edge they move toward settle first.
        if direction < 0:
            group.sort(key=lambda obj: obj["top"])
        else:
            group.sort(key=lambda obj: obj["bottom"], reverse=True)

        occupied = set()
        for obj in group:
            shift = 0
            while True:
                next_shift = shift + direction
                candidate = [(y + next_shift, x) for y, x in obj["cells"]]
                if any(y < 0 or y >= h or (y, x) in occupied
                       for y, x in candidate):
                    break
                shift = next_shift

            final_cells = [(y + shift, x) for y, x in obj["cells"]]
            for y, x in final_cells:
                occupied.add((y, x))
                result[y][x] = obj["color"]

    # Hollow/closed shapes rise; open shapes fall. Each group stacks only
    # against other shapes moving in the same direction.
    move_group([o for o in objects if o["closed"]], -1)
    move_group([o for o in objects if not o["closed"]], 1)

    return result
